internal sealed partial class ModernWorkspace {
 bool restoringWorkspace,workspaceSessionInitialized;string workspaceSnapshot="";
 void CaptureWorkspaceSession(){if(restoringWorkspace||owner.IsPreview||store.Value.settings.PrivacyMode||!WorkspaceEnhancements.Pages.Contains(selected))return;if(!workspaceSessionInitialized){workspaceSessionInitialized=true;if(store.Value.settings.enhancements.restoreSession){Dispatcher.BeginInvoke(new Action(()=>RestoreWorkspaceSession(true)));return;}}var s=new SavedWorkspaceSession{page=selected,project=openProject??"",document=selected=="Documents locaux"?openDocument??"":"",sideDocument=sideDocument??"",tabs=openTabs.Where(t=>WorkspaceEnhancements.Pages.Contains(t.Page)).Take(5).Select(t=>new SavedWorkspaceTab{page=t.Page,project=t.Project??"",document=t.Document??""}).ToList()};string json=new System.Web.Script.Serialization.JavaScriptSerializer().Serialize(s);if(json==workspaceSnapshot)return;var old=store.Value.settings.enhancements.session;store.Value.settings.enhancements.session=s;if(owner.Save())workspaceSnapshot=json;else store.Value.settings.enhancements.session=old;}
 void RestoreWorkspaceSession(bool explicitRequest=false,bool previewTest=false){if(owner.IsPreview&&!previewTest||store.Value.settings.PrivacyMode||!explicitRequest&&!store.Value.settings.enhancements.restoreSession)return;workspaceSessionInitialized=true;var s=store.Value.settings.enhancements.session;restoringWorkspace=true;try{openTabs.Clear();foreach(var t in s.tabs){if(!String.IsNullOrEmpty(t.document)&&!WorkspaceEnhancements.LocalDocument(t.document)||!WorkspaceEnhancements.ProjectExists(store.Value,t.project))continue;openTabs.Add(new WorkspaceTab{Page=t.page,Project=t.project,Document=t.document});}selected=WorkspaceEnhancements.Pages.Contains(s.page)?s.page:"Aujourd’hui";openProject=WorkspaceEnhancements.ProjectExists(store.Value,s.project)?s.project??"":"";openDocument=WorkspaceEnhancements.LocalDocument(s.document)?s.document:"";sideDocument=WorkspaceEnhancements.LocalDocument(s.sideDocument)?s.sideDocument:"";}finally{restoringWorkspace=false;}if(explicitRequest)Refresh();}
 void EnhancedHomeTools(Panel root){var row=new WrapPanel{Margin=new Thickness(0,0,0,12)};row.Children.Add(Btn("Dispositions",SavedLayouts,false,true));row.Children.Add(Btn("Reprendre ma session",()=>RestoreWorkspaceSession(true),false,true));row.Children.Add(Btn("Bilan de la journée",DailyReviewDialog,false,true));row.Children.Add(Btn("Connexions",ConnectionDiagnostics,false,true));root.Children.Add(row);}
 void SavedLayouts(){StackPanel body,actions;var w=Dialog("Mes dispositions d’accueil",out body,out actions,650);body.Children.Add(T("Déplacez et redimensionnez les blocs sur l’accueil, puis enregistrez votre disposition ici.",12,Muted));var name=new TextBox{MaxLength=60};Field(body,"Nom de la disposition",name);var error=T("",11,Accent);body.Children.Add(error);actions.Children.Add(Btn("Enregistrer l’accueil actuel",()=>{try{PersonalWorkflows.Change(store,()=>WorkspaceEnhancements.SaveLayout(store.Value,name.Text));FinishFinanceDialog(w);}catch(Exception ex){error.Text=ex.Message;}},true));foreach(var layout in store.Value.settings.enhancements.layouts.ToList()){var item=layout;var row=new WrapPanel();row.Children.Add(Btn(item.name,()=>{ChangeDay(()=>WorkspaceEnhancements.ApplyLayout(store.Value,item.id));w.Close();},false,true));row.Children.Add(Btn("Remplacer par l’accueil actuel",()=>{ChangeDay(()=>WorkspaceEnhancements.SaveLayout(store.Value,item.name));w.Close();},false,true));row.Children.Add(Btn("Supprimer",()=>{ChangeDay(()=>store.Value.settings.enhancements.layouts.RemoveAll(l=>l.id==item.id));w.Close();},false,true));body.Children.Add(row);}var restore=new CheckBox{Content="Retrouver mes onglets et panneaux au démarrage",IsChecked=store.Value.settings.enhancements.restoreSession,Margin=new Thickness(0,16,0,0)};restore.Click+=delegate{ChangeDay(()=>store.Value.settings.enhancements.restoreSession=restore.IsChecked==true);};body.Children.Add(restore);ShowWindow(w);}
 void DailyReviewDialog(){StackPanel body,actions;var w=Dialog("Bilan de la journée",out body,out actions,760);string today=DateTime.Today.ToString("yyyy-MM-dd");var done=WorkspaceEnhancements.Completed(store.Value,today);body.Children.Add(T(done.Count+" tâche(s) terminée(s) aujourd’hui",21,Ink));foreach(var t in done)body.Children.Add(T("✓ "+t.title,12,Muted));body.Children.Add(T("Choisissez les tâches à reporter à demain. Les autres dates restent conservées.",12,Muted));var selectedIds=new List<string>();foreach(var task in store.Value.tasks.Where(t=>t.status!="done"&&(t.status=="doing"||!String.IsNullOrEmpty(t.due)&&String.CompareOrdinal(t.due,today)<=0)).Take(150)){var item=task;var check=new CheckBox{Content=item.title,Margin=new Thickness(0,5,0,5)};check.Click+=delegate{selectedIds.Remove(item.id);if(check.IsChecked==true)selectedIds.Add(item.id);};body.Children.Add(check);}var prior=store.Value.settings.enhancements.reviews.FirstOrDefault(r=>r.date==today);var note=new TextBox{Text=prior==null?"":prior.note,AcceptsReturn=true,TextWrapping=TextWrapping.Wrap,MinHeight=90,MaxLength=4000};Field(body,"À retenir / préparer pour demain",note);var error=T("",11,Accent);body.Children.Add(error);actions.Children.Add(Btn("Enregistrer le bilan",()=>{try{WorkspaceEnhancements.Review(store,note.Text,selectedIds,DateTime.Today);FinishFinanceDialog(w);}catch(Exception ex){error.Text=ex.Message;}},true));foreach(var r in store.Value.settings.enhancements.reviews.Take(7))body.Children.Add(T(r.date+" · "+r.completed.Count+" terminées · "+r.postponed.Count+" reportées\n"+r.note,11,Muted));ShowWindow(w);}
 void ConnectionDiagnostics(){StackPanel body,actions;var w=Dialog("État des connexions",out body,out actions,720);var cancel=new CancellationTokenSource();w.Closed+=delegate{cancel.Cancel();};body.Children.Add(T("Les sessions enregistrées sont affichées localement. Tester vérifie les accès sans modifier vos fichiers ou votre musique.",12,Muted));var google=T("Google : session non vérifiée",12,Ink);var spotify=T("Spotify : session non vérifiée",12,Ink);var desktop=T("Lecteur Windows : non vérifié",12,Ink);var calendar=T(CalendarSession()==null?"Google Agenda : autorisation non disponible":"Google Agenda : accès à tester",12,Muted);try{google.Text=GoogleClient.Vault.Read<GoogleSession>("session")==null?"Google : non connecté":"Google : session enregistrée · accès à tester";}catch{google.Text="Google : session locale illisible · reconnectez le compte";}try{spotify.Text=Spotify.Storage.Session==null?"Spotify : non connecté":"Spotify : session enregistrée · accès à tester";}catch{spotify.Text="Spotify : session locale illisible · reconnectez le compte";}body.Children.Add(google);body.Children.Add(calendar);body.Children.Add(spotify);body.Children.Add(desktop);var bot=T(String.IsNullOrEmpty(store.Value.settings.enhancements.botHealthUrl)?"Bot Discord : point de contrôle non configuré":"Bot Discord : point de contrôle enregistré · à tester",12,Muted);if(store.Value.settings.EnableBotModule)body.Children.Add(bot);var botUrl=new TextBox{Text=store.Value.settings.enhancements.botHealthUrl,MaxLength=2048};if(store.Value.settings.EnableBotModule)Field(body,"Point de santé du bot · URL publique sans jeton",botUrl);if(store.Value.settings.EnableBotModule)body.Children.Add(Btn("Enregistrer le point de contrôle",()=>{try{WorkspaceEnhancements.ValidateHealthUrl(botUrl.Text.Trim());PersonalWorkflows.Change(store,()=>store.Value.settings.enhancements.botHealthUrl=botUrl.Text.Trim());bot.Text=String.IsNullOrEmpty(botUrl.Text.Trim())?"Bot Discord : point de contrôle non configuré":"Bot Discord : point de contrôle enregistré · à tester";}catch(Exception ex){bot.Text=ex.Message;}},false,true));var test=Btn("Tester les connexions",()=>{},true);test.Click+=async delegate{if(owner.IsPreview)return;test.IsEnabled=false;try{try{await GoogleClient.List("",true,"",cancel.Token);if(!cancel.IsCancellationRequested)google.Text="Google Drive : accès confirmé";}catch(Exception ex){if(!cancel.IsCancellationRequested)google.Text="Google : "+WorkspaceEnhancements.SafeDiagnostic(ex);}if(CalendarSession()!=null)try{await CalendarApi.Calendars(cancel.Token);if(!cancel.IsCancellationRequested)calendar.Text="Google Agenda : accès confirmé";}catch(Exception ex){if(!cancel.IsCancellationRequested)calendar.Text="Google Agenda : "+WorkspaceEnhancements.SafeDiagnostic(ex);}try{await Spotify.Playlists(0,cancel.Token);if(!cancel.IsCancellationRequested)spotify.Text="Spotify : bibliothèque accessible";}catch(Exception ex){if(!cancel.IsCancellationRequested)spotify.Text="Spotify : "+WorkspaceEnhancements.SafeDiagnostic(ex);}if(store.Value.settings.EnableBotModule)try{string status=await WorkspaceEnhancements.CheckBot(store.Value.settings.enhancements.botHealthUrl,cancel.Token);if(!cancel.IsCancellationRequested)bot.Text="Bot Discord : "+status;}catch(Exception ex){if(!cancel.IsCancellationRequested)bot.Text="Bot Discord : "+WorkspaceEnhancements.SafeDiagnostic(ex);}try{var state=await desktopMusic.Read();if(!cancel.IsCancellationRequested)desktop.Text=state.Available?"Lecteur Windows : Spotify détecté":"Lecteur Windows : aucun Spotify détecté · lancez un morceau";}catch{if(!cancel.IsCancellationRequested)desktop.Text="Lecteur Windows : indisponible";}}finally{if(!cancel.IsCancellationRequested)test.IsEnabled=true;}};actions.Children.Add(test);actions.Children.Add(Btn("Configurer Google",()=>{w.Close();Go("Google Drive");},false,true));actions.Children.Add(Btn("Configurer Spotify",()=>{w.Close();Go("Ma musique");},false,true));if(store.Value.settings.EnableBotModule)actions.Children.Add(Btn("Réglages du bot",()=>{w.Close();Go("Réglages");},false,true));ShowWindow(w);}
}
